export default rule {
  starting_at $PARENT
  formula {
    always([+modifies(/model) -all_signed(/maintainers)] false)
  }
}

export default rule {
  starting_at $PARENT
  formula {
    always([+modifies(/releases) -signed_by(/keys/ci.id)] false)
  }
}

export default rule {
  starting_at $PARENT
  formula {
    always([+modifies(/rules) -all_signed(/maintainers)] false)
  }
}

export default rule {
  starting_at $PARENT
  formula {
    always([+modifies(/keys) -all_signed(/maintainers)] false)
  }
}

export default rule {
  starting_at $PARENT
  formula {
    always([+modifies(/maintainers) -all_signed(/maintainers)] false)
  }
}

model release {
  part flow {
    q0 --> q1
    q1 --> q1: +signed_by(/keys/ci.id) -modifies(/keys) -modifies(/maintainers) -modifies(/rules) -modifies(/model)
    q1 --> q1: +all_signed(/maintainers) -modifies(/releases)
  }
}
